script:
/* The native post editor (write_*.js). Sizes were measured from the old page. */

#cafe-write {
  --w-outline: #ededed;
  --w-outline-2: #e2e2e2;
  --w-surface: #f3f3f3;
  --w-ink: #0f0f0f;
  --w-ink-8: #383838;
  --w-ink-5: #7c7c7c;
  --w-ink-4: #999999;
  font-family: 'InterVar', ui-sans-serif, system-ui, sans-serif;
  font-size: 14px;
  font-weight: 420;
  letter-spacing: 0.02em;
  line-height: 1.15;
  color: var(--w-ink);
}
#cafe-write *,
#cafe-write *::before,
#cafe-write *::after {
  box-sizing: border-box;
}
#cafe-write [hidden],
.cafe-w-btn[hidden],
.cafe-w-more[hidden],
.cafe-w-menu [hidden] {
  display: none !important;
}
.cafe-w-icon {
  display: inline-flex;
  flex-shrink: 0;
}
.cafe-w-icon svg {
  width: 100%;
  height: 100%;
}
.cafe-w-small {
  width: 16px;
  height: 16px;
}
.cafe-w-large {
  width: 32px;
  height: 32px;
}

/* ---- Header buttons ---- */
.cafe-w-btn:hover:not(:disabled) {
  background: #f8f8f8 !important;
}
.cafe-w-btn.cafe-btn-solid:hover:not(:disabled) {
  background: #383838 !important;
}
.cafe-w-btn.busy {
  position: relative;
  cursor: default;
}
.cafe-w-btn.busy span {
  visibility: hidden;
}
.cafe-w-btn.busy::after {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 14px;
  height: 14px;
  margin: -7px 0 0 -7px;
  border: 2px solid currentColor;
  border-right-color: transparent;
  border-radius: 9999px;
  content: '';
  animation: cafe-w-spin 0.7s linear infinite;
}
@keyframes cafe-w-spin {
  to {
    transform: rotate(360deg);
  }
}
.cafe-w-more:hover {
  background: #ededed !important;
}

/* ---- The page ---- */
.cafe-w-scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}
.cafe-w-page {
  width: 100%;
  max-width: 600px;
  margin: 0 auto;
  padding: 40px 0;
}
.cafe-w-loading {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.cafe-w-loading .cafe-skeleton {
  height: 14px;
  border-radius: 4px;
  background: linear-gradient(90deg, #f3f3f3, #fafafa, #f3f3f3);
  background-size: 200% 100%;
  animation: cafe-pulse 1.2s ease-in-out infinite;
}
.cafe-w-status {
  margin: 0;
  color: var(--w-ink-5);
  font-size: 13px;
  line-height: 14.95px;
  text-align: center;
}
.cafe-w-toolbar {
  display: flex;
  width: fit-content;
  max-width: 100%;
  align-items: center;
  gap: 4px;
  margin-top: 16px;
  padding: 4px 8px;
  overflow-x: auto;
  border: 1px solid var(--w-outline-2);
  border-radius: 9999px;
  background: #fff;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);
  scrollbar-width: none;
}
.cafe-w-toolbar::-webkit-scrollbar {
  display: none;
}
.cafe-w-tool {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  gap: 6px;
  width: 28px;
  height: 28px;
  padding: 0;
  border: 0;
  border-radius: 8px;
  background: none;
  color: #171717;
  font-size: 13px;
  cursor: pointer;
}
.cafe-w-tool:hover {
  background: var(--w-surface);
}
.cafe-w-tool.on,
.cafe-w-tool[aria-pressed='true'] {
  background: #e2e2e2;
}
.cafe-w-sep {
  width: 1px;
  height: 20px;
  margin: 0 4px;
  flex-shrink: 0;
}
.cafe-w-title {
  display: block;
  width: 100%;
  margin-top: 16px;
  padding: 0;
  border: 0;
  outline: none;
  background: transparent;
  color: #0f0f0f;
  font: inherit;
  font-size: 24px;
  font-weight: 600;
  letter-spacing: 0.005em;
  line-height: 33.6px;
}
.cafe-w-title::placeholder {
  color: var(--w-ink-4);
  opacity: 1;
}
.cafe-w-editor {
  min-height: calc(100vh - 320px);
  margin-top: 16px;
  color: var(--w-ink-8);
}
.cafe-w-prose {
  min-height: calc(100vh - 320px);
  outline: none;
  color: #171717;
  font-size: 15px;
  line-height: 25.5px;
  letter-spacing: 0.02em;
}
.cafe-w-prose > * + * {
  margin-top: 16px;
}
.cafe-w-prose p {
  margin: 0;
}
.cafe-w-prose h1,
.cafe-w-prose h2,
.cafe-w-prose h3,
.cafe-w-prose h4 {
  margin-bottom: 0;
  color: #0f0f0f;
  font-weight: 600;
}
.cafe-w-prose > h1,
.cafe-w-prose > h2,
.cafe-w-prose > h3,
.cafe-w-prose > h4 {
  margin-top: 24px;
}
.cafe-w-prose > :first-child {
  margin-top: 0;
}
.cafe-w-prose > h1 + *,
.cafe-w-prose > h2 + *,
.cafe-w-prose > h3 + *,
.cafe-w-prose > h4 + * {
  margin-top: 8px;
}
.cafe-w-prose h1 { font-size: 25.7143px; line-height: 32px; }
.cafe-w-prose h2 { font-size: 19.2857px; line-height: 26.0357px; }
.cafe-w-prose h3 { font-size: 17.1429px; line-height: 24px; }
.cafe-w-prose h4 { font-size: 15px; line-height: 21px; }
.cafe-w-prose strong {
  font-weight: 600;
}
.cafe-w-prose p.is-editor-empty:first-child::before {
  float: left;
  height: 0;
  color: var(--w-ink-4);
  content: attr(data-placeholder);
  pointer-events: none;
}
.cafe-w-prose blockquote {
  margin-left: 0;
  padding-left: 15px;
  border-left: 2px solid #c2c2c2;
  color: #525252;
  font-weight: 500;
}
.cafe-w-prose ul,
.cafe-w-prose ol {
  margin-bottom: 0;
  padding-left: 22.5px;
}
.cafe-w-prose ol {
  padding-left: 25.5px;
}
.cafe-w-prose li + li {
  margin-top: 4px;
}
.cafe-w-prose > ul + ol,
.cafe-w-prose > ol + ul,
.cafe-w-prose > ul + ul,
.cafe-w-prose > ol + ol {
  margin-top: 4px;
}
.cafe-w-prose ul li::marker {
  color: #c8c8c8;
}
.cafe-w-prose ol li::marker {
  color: #999;
}
.cafe-w-prose li > p {
  margin: 0;
}
.cafe-w-prose ul {
  list-style: disc;
}
.cafe-w-prose ol {
  list-style: decimal;
}
.cafe-w-prose code {
  padding: 1px 4px;
  border-radius: 4px;
  background: rgba(0, 0, 0, 0.07);
  font-size: 14px;
}
.cafe-w-prose pre {
  padding: 12px 16px;
  overflow-x: auto;
  border-radius: 8px;
  background: #f3f3f3;
}
.cafe-w-prose pre code {
  padding: 0;
  background: none;
}
.cafe-w-prose a {
  color: #0f0f0f;
  font-weight: 500;
  text-decoration: underline;
}
.cafe-w-prose mark {
  background: #ffe97a;
}

/* An image in the story: the same 16:9 crop the published post has. */
.cafe-w-image {
  display: block;
  margin: 16px 0;
}
.cafe-w-image-box {
  position: relative;
  display: block;
  width: 100%;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  border-radius: 4px;
  background: var(--w-surface);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);
}
.cafe-w-image-box img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  cursor: grab;
}
.cafe-w-image.selected .cafe-w-image-box {
  outline: 2px solid #999;
  outline-offset: 2px;
}
.cafe-w-image-status {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background: rgba(255, 255, 255, 0.7);
  color: var(--w-ink-5);
  font-size: 13px;
}
.cafe-w-image-status:empty {
  display: none;
}
.cafe-w-image.failed .cafe-w-image-status {
  color: #b41d1d;
}
.cafe-w-image-caption-btn {
  position: absolute;
  top: 8px;
  right: 8px;
  display: none;
  height: 24px;
  padding: 0 8px;
  border: 0;
  border-radius: 6px;
  background: rgba(0, 0, 0, 0.7);
  color: #fff;
  font-size: 12px;
  cursor: pointer;
}
.cafe-w-image:hover .cafe-w-image-caption-btn,
.cafe-w-image.selected .cafe-w-image-caption-btn {
  display: block;
}
.cafe-w-caption {
  display: block;
  width: 100%;
  height: 28px;
  margin-top: 0;
  padding: 0;
  border: 0;
  outline: none;
  background: transparent;
  color: var(--w-ink-5);
  font: inherit;
  font-size: 14px;
  text-align: center;
}
.cafe-w-prose div[data-type='image-group'] {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
  gap: 8px;
}
.cafe-w-prose div[data-type='image-group'] .cafe-w-image {
  margin: 0;
}

/* ---- Tags and errors ---- */
.cafe-w-tags {
  margin-top: 32px;
}
.cafe-w-tags label {
  display: block;
  margin-bottom: 6px;
  color: var(--w-ink-5);
  font-size: 14px;
}
/* Matches frappe-ui's own MultiEmailInput (the closest first-party
   pills-in-an-input component): box = rounded-4/bg-surface-gray-2, chip =
   rounded-4 bordered bg-surface-base (not a filled pill), remove icon =
   size-3 with no button chrome, panel = rounded-6/shadow-2xl, item rows =
   rounded-4 with a soft hover tint. */
.cafe-w-tag-box {
  position: relative;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  width: 100%;
  min-height: 28px;
  padding: 4px 6px;
  border-radius: 8px;
  background: var(--w-surface);
  transition: box-shadow 0.15s ease;
}
.cafe-w-tag-box:focus-within {
  box-shadow: 0 0 0 2px rgba(15, 15, 15, 0.12);
}
.cafe-w-tag-fields {
  display: flex;
  flex: 1;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  min-width: 0;
}
.cafe-w-tag-chips {
  display: contents;
}
.cafe-w-tag-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 2px 2px 10px;
  border-radius: 9999px;
  background: #e2e2e2;
  color: #171717;
  font-size: 13px;
  white-space: nowrap;
}
.cafe-w-tag-x {
  display: grid;
  place-items: center;
  width: 18px;
  height: 18px;
  padding: 0;
  border: 0;
  border-radius: 9999px;
  background: none;
  color: #7c7c7c;
  cursor: pointer;
}
.cafe-w-tag-x:hover {
  background: rgba(0, 0, 0, 0.08);
}
.cafe-w-tag-fields input {
  flex: 1 1 auto;
  min-width: 96px;
  padding: 2px;
  border: 0;
  outline: none;
  background: none;
  color: var(--w-ink-8);
  font: inherit;
  font-size: 14px;
}
.cafe-w-tag-fields input::placeholder {
  color: var(--w-ink-4);
  opacity: 1;
}
.cafe-w-tag-toggle {
  display: grid;
  flex-shrink: 0;
  place-items: center;
  width: 20px;
  height: 20px;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: none;
  color: var(--w-ink-4);
  cursor: pointer;
}
.cafe-w-tag-toggle:hover {
  color: var(--w-ink-8);
}
.cafe-w-tag-toggle .cafe-w-icon {
  transition: transform 0.2s cubic-bezier(0.23, 1, 0.32, 1);
}
.cafe-w-tag-toggle.open .cafe-w-icon {
  transform: rotate(180deg);
}
.cafe-w-tag-results {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  right: 0;
  z-index: 5;
  max-height: 240px;
  overflow-y: auto;
  padding: 4px;
  border-radius: 10px;
  background: #fff;
  box-shadow:
    0 0 0 1px rgba(0, 0, 0, 0.05),
    0 20px 40px -10px rgba(0, 0, 0, 0.25);
}
.cafe-w-tag-option {
  display: flex;
  align-items: center;
  width: 100%;
  min-height: 28px;
  padding: 6px 8px;
  border: 0;
  border-radius: 8px;
  background: none;
  color: var(--w-ink-8);
  font: inherit;
  font-size: 14px;
  text-align: left;
  cursor: pointer;
}
.cafe-w-tag-option:hover {
  background: rgba(15, 15, 15, 0.045);
}
.cafe-w-error {
  margin: 12px 0 0;
  color: #b41d1d;
  font-size: 13px;
}

/* ---- Menus and the selection bar ---- */
.cafe-w-menu,
.cafe-w-bubble {
  position: fixed;
  z-index: 70;
  border-radius: 8px;
  background: #fff;
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.08), 0 8px 24px rgba(0, 0, 0, 0.12);
  font-family: 'InterVar', ui-sans-serif, system-ui, sans-serif;
  font-size: 14px;
  font-weight: 420;
  letter-spacing: 0.02em;
  color: #171717;
}
.cafe-w-menu {
  min-width: 160px;
  padding: 4px;
}
.cafe-w-menu-item {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 8px;
  height: 28px;
  padding: 0 8px;
  border: 0;
  border-radius: 6px;
  background: none;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.cafe-w-menu-item:hover,
.cafe-w-menu-item.active {
  background: var(--cafe-surface-2, #f3f3f3);
}
.cafe-w-menu-item.danger {
  color: #b41d1d;
}
.cafe-w-menu .cafe-w-icon {
  color: #7c7c7c;
}
.cafe-w-menu-item.danger .cafe-w-icon {
  color: inherit;
}
.cafe-w-bubble {
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 4px;
}
.cafe-w-bubble[hidden] {
  display: none;
}

/* ---- Story preview ---- */
.cafe-dialog.cafe-w-story-dialog {
  max-width: 576px;
}
.cafe-w-cover {
  position: relative;
  width: 100%;
  aspect-ratio: 1.91;
  overflow: hidden;
  border-radius: 6px;
  background: var(--cafe-surface-2, #f3f3f3);
}
.cafe-w-cover img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.cafe-w-cover-empty {
  display: grid;
  width: 100%;
  height: 100%;
  place-items: center;
  color: #999;
}
.cafe-w-cover-over {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: rgba(0, 0, 0, 0);
  opacity: 0;
  transition: background 0.15s, opacity 0.15s;
}
.cafe-w-cover:hover .cafe-w-cover-over {
  background: rgba(0, 0, 0, 0.4);
  opacity: 1;
}
.cafe-w-cover-btn {
  padding: 6px 12px;
  border: 0;
  border-radius: 6px;
  background: rgba(0, 0, 0, 0.7);
  color: #fff;
  font: inherit;
  font-size: 14px;
  cursor: pointer;
}
.cafe-w-cover-btn:hover {
  background: rgba(0, 0, 0, 0.85);
}
.cafe-w-read {
  margin: 8px 0 0;
  color: #7c7c7c;
  font-size: 13px;
}
.cafe-w-story-title,
.cafe-w-story-excerpt {
  display: block;
  width: 100%;
  margin: 8px 0 0;
  padding: 8px 0 0;
  border: 0;
  border-top: 1px solid #ededed;
  outline: none;
  background: transparent;
  font: inherit;
  resize: none;
}
.cafe-w-story-title {
  color: #171717;
  font-size: 18px;
  font-weight: 600;
}
.cafe-w-story-excerpt {
  margin-top: 4px;
  color: #525252;
  font-size: 13px;
  line-height: 1.5;
}
.cafe-w-story-title::placeholder,
.cafe-w-story-excerpt::placeholder {
  color: #999;
}
.cafe-w-story-note {
  margin: 8px 0 0;
  color: #999;
  font-size: 12px;
}
.cafe-w-adjust-hint {
  margin: 0 0 12px;
  color: #525252;
  font-size: 13px;
}
.cafe-w-frame {
  position: relative;
  width: 100%;
  aspect-ratio: 1.91;
  overflow: hidden;
  border-radius: 6px;
  background: #000;
  cursor: default;
  user-select: none;
  touch-action: none;
}
.cafe-w-frame.movable {
  cursor: move;
}

/* ---- Phone ---- */
@media (max-width: 767px) {
  .cafe-write-main {
    flex-grow: 0 !important;
    height: calc(100vh - 57px) !important;
  }
  .cafe-w-page {
    padding: 24px 16px;
  }
}
